import React, { useState } from 'react';
import './Testimonials.css';

interface Testimonial {
  quote: string;
  author: string;
  role: string;
  company: string;
  funded: string;
  rating: number;
}

const FOUNDER_TESTIMONIALS: Testimonial[] = [
  {
    quote: 'Mercury is the first financial institution that feels like software designed by engineers for engineers. The automated yield on our treasury reserves alone covers our monthly cloud infrastructure spend.',
    author: 'Julian Thorne',
    role: 'Co-Founder & CEO',
    company: 'HyperScale AI',
    funded: 'Series B • $38M Raised',
    rating: 5,
  },
  {
    quote: 'We operate across four international entities. Managing cross-border wires and employee IO cards without branch visits or wire hold fees saved us hundreds of operational hours.',
    author: 'Camilla Valenzuela',
    role: 'VP of Finance & Ops',
    company: 'Sora Robotics',
    funded: 'Series A • $16M Raised',
    rating: 5,
  },
  {
    quote: 'The $5M sweep network gave our board total peace of mind after the regional banking shakeups. Having yield optimization happen automatically overnight without manual wire transfers is transformative.',
    author: 'Marcus Vance',
    role: 'Founder & CTO',
    company: 'Aether Grid Systems',
    funded: 'Seed • $6.5M Raised',
    rating: 5,
  },
];

export function Testimonials() {
  const [currentIndex, setCurrentIndex] = useState(0);

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev === 0 ? FOUNDER_TESTIMONIALS.length - 1 : prev - 1));
  };

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev === FOUNDER_TESTIMONIALS.length - 1 ? 0 : prev + 1));
  };

  const active = FOUNDER_TESTIMONIALS[currentIndex];

  return (
    <section className="mercury-testimonials" id="testimonials" aria-label="Founder Endorsements">
      <div className="mercury-testimonials__inner">
        <div className="mercury-testimonials__header">
          <p className="mercury-testimonials__eyebrow">Founder Testimonials</p>
          <h2 className="mercury-testimonials__title">Trusted by 100,000+ Fast-Growing Technology Startups</h2>
        </div>

        <div className="mercury-testimonials__carousel">
          <div className="mercury-testimonials__card">
            <div className="mercury-testimonials__stars">
              {Array.from({ length: active.rating }).map((_, i) => (
                <span key={i} className="mercury-testimonials__star">★</span>
              ))}
            </div>

            <blockquote className="mercury-testimonials__quote">
              “{active.quote}”
            </blockquote>

            <div className="mercury-testimonials__footer">
              <div className="mercury-testimonials__author-block">
                <span className="mercury-testimonials__name">{active.author}</span>
                <span className="mercury-testimonials__meta">
                  {active.role}, <strong className="mercury-testimonials__company">{active.company}</strong>
                </span>
                <span className="mercury-testimonials__funding">{active.funded}</span>
              </div>

              <div className="mercury-testimonials__nav">
                <button
                  type="button"
                  onClick={prevSlide}
                  className="mercury-testimonials__nav-btn"
                  aria-label="Previous quote"
                >
                  ←
                </button>
                <span className="mercury-testimonials__page">
                  0{currentIndex + 1} / 0{FOUNDER_TESTIMONIALS.length}
                </span>
                <button
                  type="button"
                  onClick={nextSlide}
                  className="mercury-testimonials__nav-btn"
                  aria-label="Next quote"
                >
                  →
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
